func newLeasedWriterConfig(opts ...LeasedWriterOption) *leasedwriterConfig {
	c := &leasedwriterConfig{
		Fixture: DefaultLeasedWriterFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	// Derived: Acquire is classified writer, so the interface
	// populates itself and a reader has something to read.
	c.seed = func(ctx context.Context, subject leasedidempotentwriter.LeasedWriter) error {
		return subject.Acquire(ctx, c.Fixture.Key)
	}
	c.seedIsDerived = true
	for _, o := range opts {
		o(c)
	}
	return c
}

